// Some portions generated by Co-Pilot
import { renderHook, waitFor } from "@testing-library/react";
import axios, { AxiosHeaders, type AxiosResponse } from "axios";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { useAdoptiumContributorsApi } from "../useAdoptiumContributorsApi";

vi.unmock("@/hooks/useAdoptiumContributorsApi");

const human = {
  login: "human-contributor",
  type: "User",
  avatar_url: "https://avatars.githubusercontent.com/u/1",
  html_url: "https://github.com/human-contributor",
  contributions: 42,
};

const copilot = {
  ...human,
  login: "Copilot",
  type: "Bot",
  html_url: "https://github.com/apps/copilot-swe-agent",
};

function response(
  data: unknown,
  headers: Record<string, string> = {},
): AxiosResponse<unknown> {
  return {
    data,
    headers,
    status: 200,
    statusText: "OK",
    config: { headers: new AxiosHeaders() },
  };
}

describe("Random human contributors", () => {
  beforeEach(() => {
    window.localStorage.clear();
    window.localStorage.setItem("temurin-build_max_contributors", "10");
    window.localStorage.setItem("temurin-build_fetch_date", String(Date.now()));
    vi.spyOn(Math, "random").mockReturnValue(0);
    vi.spyOn(axios, "get").mockResolvedValue(response([human]));
  });

  afterEach(() => {
    vi.restoreAllMocks();
    window.localStorage.clear();
  });

  it("returns an eligible human with the existing profile and contribution links", async () => {
    const { result } = renderHook(() => useAdoptiumContributorsApi(true));
    await waitFor(() => expect(result.current?.login).toBe(human.login));
    expect(result.current).toEqual({
      avatarUri: human.avatar_url,
      commitsListUri: `https://github.com/adoptium/temurin-build/commits?author=${human.login}`,
      repo: "temurin-build",
      contributionsCount: human.contributions,
      login: human.login,
      profileUri: human.html_url,
    });
  });

  it.each([
    copilot,
    { ...human, login: "copilot" },
    { ...human, login: "github-copilot" },
    { ...human, login: "new-automation-app", type: "Bot" },
    { ...human, login: "new-automation-app[BoT]" },
    { ...human, login: "DEPENDABOT[BOT]" },
    { ...human, login: "ECLIPSE-TEMURIN-BOT" },
    { ...human, html_url: "https://github.com/apps/some-app" },
  ])(
    "rejects automated account $login and retries for a human",
    async (account) => {
      vi.mocked(axios.get)
        .mockResolvedValueOnce(response([account]))
        .mockResolvedValueOnce(response([human]));
      const { result } = renderHook(() => useAdoptiumContributorsApi(true));
      await waitFor(() => expect(result.current?.login).toBe(human.login));
      expect(axios.get).toHaveBeenCalledTimes(2);
    },
  );

  it("never returns a bot after all retry attempts are exhausted", async () => {
    vi.mocked(axios.get).mockResolvedValue(response([copilot]));
    const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
    const { result } = renderHook(() => useAdoptiumContributorsApi(true));
    await waitFor(() =>
      expect(warn).toHaveBeenCalledWith(
        "No eligible human contributor found for repository:",
        "temurin-build",
      ),
    );
    expect(axios.get).toHaveBeenCalledTimes(3);
    expect(result.current).toBeNull();
  });

  it("uses the freshly fetched contributor count for retry page selection", async () => {
    window.localStorage.clear();
    vi.mocked(Math.random)
      .mockReturnValueOnce(0)
      .mockReturnValueOnce(0.9)
      .mockReturnValue(0.5);
    vi.mocked(axios.get)
      .mockResolvedValueOnce(
        response([human], {
          link: '<https://api.github.com/repos/adoptium/temurin-build/contributors?per_page=1&page=10>; rel="last"',
        }),
      )
      .mockResolvedValueOnce(response([copilot]))
      .mockResolvedValueOnce(response([human]));
    const { result } = renderHook(() => useAdoptiumContributorsApi(true));
    await waitFor(() => expect(result.current?.login).toBe(human.login));
    expect(axios.get).toHaveBeenNthCalledWith(
      3,
      "https://api.github.com/repos/adoptium/temurin-build/contributors?per_page=1&page=6",
    );
    expect(window.localStorage.getItem("temurin-build_max_contributors")).toBe(
      "10",
    );
  });

  it("does not fetch contributors for hidden cards", () => {
    const { result } = renderHook(() => useAdoptiumContributorsApi(false));
    expect(axios.get).not.toHaveBeenCalled();
    expect(result.current).toBeNull();
  });

  it("reports network failures instead of silently returning a contributor", async () => {
    const error = new Error("GitHub unavailable");
    vi.mocked(axios.get).mockRejectedValue(error);
    const logError = vi.spyOn(console, "error").mockImplementation(() => {});
    const { result } = renderHook(() => useAdoptiumContributorsApi(true));
    await waitFor(() =>
      expect(logError).toHaveBeenCalledWith(
        "Error fetching contributor:",
        error,
      ),
    );
    expect(result.current).toBeNull();
  });
});
